    static Data d;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)] static void Reset() { d = null; }

    public static Data Get() { return d ?? Load(); }

    static Data Load()
    {
        Data r = null;
        try { string t = DataPath.ReadText("hud_layout.json"); if (!string.IsNullOrEmpty(t)) r = JsonUtility.FromJson<Data>(t.TrimStart((char)0xFEFF)); }
        catch (Exception e) { Debug.LogWarning("[HudLayout] hud_layout.json unreadable, using the built-in defaults: " + e.Message); r = null; }
        var def = new Data();
        if (r == null || !r.enabled) r = def;
        else
        {
            if (r.draw.minorWords == null) r.draw.minorWords = def.draw.minorWords;
            if (r.barFx.capBack == null || r.barFx.capBack.Length < 3) r.barFx.capBack = def.barFx.capBack;
            if (r.flow.hintColor == null || r.flow.hintColor.Length < 3) r.flow.hintColor = def.flow.hintColor;
            if (r.flow.hintOpen == null) r.flow.hintOpen = def.flow.hintOpen;
            if (r.flow.hintClose == null) r.flow.hintClose = def.flow.hintClose;
        }
        d = r; return d;
    }

    /// <summary>Colour from a json array (r, g, b[, a]); a missing alpha is 1.</summary>
    public static Color Col(float[] a) { return new Color(a[0], a[1], a[2], a.Length > 3 ? a[3] : 1f); }
